-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO claims, extensions;

-- Evaluate the caller identity once per statement rather than for each
-- invitation row. The admin-only access rule is unchanged.
ALTER POLICY "Admins can manage signup invitations"
ON claims.signup_invitations
USING (
  EXISTS (
    SELECT 1 FROM claims.user_roles ur
    JOIN claims.roles r ON ur.role_id = r.id
    WHERE ur.user_id = (SELECT auth.uid()) AND r.code = 'SYSTEM_ADMIN'
  )
)
WITH CHECK (
  EXISTS (
    SELECT 1 FROM claims.user_roles ur
    JOIN claims.roles r ON ur.role_id = r.id
    WHERE ur.user_id = (SELECT auth.uid()) AND r.code = 'SYSTEM_ADMIN'
  )
);
